package com.aistock.market.marketreview;
import com.aistock.common.*;import com.aistock.common.marketreview.MarketReviewContract.*;import com.aistock.market.security.*;import com.aistock.market.adminquery.AdminMarketDataAccessFilter;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.Cookie;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MarketReviewHttpTest {
 String v="11111111-1111-1111-1111-111111111111",actor="00000000-0000-0000-0000-000000000001",op="22222222-2222-2222-2222-222222222222",path="/api/v1/admin/market-data/SH600030/versions/"+v+"/reviews",origin="http://127.0.0.1:15173";SessionIdentityClient identity;MarketReviewService service;MockMvc mvc;String json;
 @BeforeEach void init()throws Exception{identity=mock(SessionIdentityClient.class);service=mock(MarketReviewService.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity(actor,"ADMIN",false,1),"t"));when(service.save(anyString(),anyString(),anyString(),any())).thenReturn(new Receipt(op,"SH600030",v,"1","REVIEWED","已核对",Instant.parse("2026-10-28T00:00:00Z")));json=new ObjectMapper().writeValueAsString(new Command(op,"0","REVIEWED","已核对"));mvc=MockMvcBuilders.standaloneSetup(new MarketReviewController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminMarketDataAccessFilter(identity,"test",new ObjectMapper())).build();}
 @Test void readRequiresAdmin()throws Exception{mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","a"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity(actor,"USER",false,1),"t"));mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","u"))).andExpect(status().isForbidden());verify(service,times(1)).read("SH600030",v);}
 @Test void writeRequiresOriginAndSingleMarkerAndDerivesActor()throws Exception{var cookie=new Cookie("AISTOCK_SESSION","a");mvc.perform(post(path).cookie(cookie).contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isForbidden());mvc.perform(post(path).cookie(cookie).header("Origin","https://evil.example").header("X-Aistock-Admin-Action","1").contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isForbidden());mvc.perform(post(path).cookie(cookie).header("Origin",origin).header("X-Aistock-Admin-Action","1","1").contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isForbidden());mvc.perform(post(path).cookie(cookie).header("Origin",origin).header("X-Aistock-Admin-Action","1").contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isOk());verify(service).save(eq("SH600030"),eq(v),eq(actor),any());}
 @Test void rejectsQueryBodyUnknownActorAndMethodWithoutWork()throws Exception{var cookie=new Cookie("AISTOCK_SESSION","a");mvc.perform(get(path).cookie(cookie).param("x","1")).andExpect(status().isBadRequest());mvc.perform(get(path).cookie(cookie).content("{}")).andExpect(status().isBadRequest());mvc.perform(post(path).cookie(cookie).header("Origin",origin).header("X-Aistock-Admin-Action","1").contentType(MediaType.APPLICATION_JSON).content(json.replace("\"note\":","\"actor\":\"spoof\",\"note\":"))).andExpect(status().isBadRequest());mvc.perform(delete(path).cookie(cookie)).andExpect(status().isNotFound());verifyNoInteractions(service);}
}
